sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Get the assignment field reference
    var assignField = 'u_assigned_to';

    // Logic to auto-suggest assignment based on request type
    if (newValue == 'Vaccination' || newValue == 'Treatment' || newValue == 'Sterilization') {
        g_form.setValue(assignField, 'vet'); // Suggest Vet
    } else if (newValue == 'Food Donation') {
        g_form.setValue(assignField, 'volunteer'); // Suggest Volunteer
    } else {
        g_form.setValue(assignField, ''); // Clear if other types
    }
}
